import Foundation

/// Hand-written minimal-but-valid OOXML .pptx generator — no external library. Produces either a
/// standard 16:9 talk deck (one slide per section) or a single large poster slide (custom canvas,
/// freeform positioned text boxes). Verified by round-tripping generated files through python-pptx.
enum PPTXBuilder {
    struct Section {
        var heading: String
        var bullets: [String]
    }

    enum BuildError: LocalizedError {
        case zipFailed(String)
        var errorDescription: String? {
            switch self {
            case .zipFailed(let message): return "Failed to package the .pptx: \(message)"
            }
        }
    }

    private static let inchToEMU = 914400

    // MARK: - Public builders

    static func buildTalkDeck(title: String, sections: [Section]) throws -> Data {
        let slideWidth = 12192000  // 13.333in, 16:9
        let slideHeight = 6858000  // 7.5in

        var slidesXML: [String] = []
        slidesXML.append(titleSlideXML(title: title, subtitle: "Generated by Maziar"))
        for section in sections {
            slidesXML.append(bodySlideXML(title: section.heading, bullets: section.bullets))
        }

        return try assemble(
            slideWidth: slideWidth, slideHeight: slideHeight, slidesXML: slidesXML, docTitle: title
        )
    }

    static func buildPoster(title: String, sections: [Section], widthInches: Double = 48, heightInches: Double = 36) throws -> Data {
        let slideWidth = Int(widthInches * Double(inchToEMU))
        let slideHeight = Int(heightInches * Double(inchToEMU))

        let slideXML = posterSlideXML(title: title, sections: sections, slideWidth: slideWidth, slideHeight: slideHeight)
        return try assemble(slideWidth: slideWidth, slideHeight: slideHeight, slidesXML: [slideXML], docTitle: title)
    }

    // MARK: - Slide content builders

    private static func titleSlideXML(title: String, subtitle: String) -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">
          <p:cSld>
            <p:spTree>
              <p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>
              <p:grpSpPr/>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="2" name="Title"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="title"/></p:nvPr></p:nvSpPr>
                <p:spPr/>
                <p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>\(xmlEscape(title))</a:t></a:r></a:p></p:txBody>
              </p:sp>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="3" name="Subtitle"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" idx="1"/></p:nvPr></p:nvSpPr>
                <p:spPr/>
                <p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>\(xmlEscape(subtitle))</a:t></a:r></a:p></p:txBody>
              </p:sp>
            </p:spTree>
          </p:cSld>
          <p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr>
        </p:sld>
        """
    }

    private static func bodySlideXML(title: String, bullets: [String]) -> String {
        let bulletParagraphs = bullets.map { bullet in
            "<a:p><a:r><a:t>\u{2022} \(xmlEscape(bullet))</a:t></a:r></a:p>"
        }.joined(separator: "\n              ")
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">
          <p:cSld>
            <p:spTree>
              <p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>
              <p:grpSpPr/>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="2" name="Title"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="title"/></p:nvPr></p:nvSpPr>
                <p:spPr/>
                <p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>\(xmlEscape(title))</a:t></a:r></a:p></p:txBody>
              </p:sp>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="3" name="Content"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" idx="1"/></p:nvPr></p:nvSpPr>
                <p:spPr/>
                <p:txBody><a:bodyPr/><a:lstStyle/>
              \(bulletParagraphs)
                </p:txBody>
              </p:sp>
            </p:spTree>
          </p:cSld>
          <p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr>
        </p:sld>
        """
    }

    private static func posterSlideXML(title: String, sections: [Section], slideWidth: Int, slideHeight: Int) -> String {
        let margin = inchToEMU / 2  // 0.5in
        let titleHeight = Int(Double(inchToEMU) * 2.2)
        var shapes: [String] = []
        var shapeId = 2

        shapes.append(freeformTextBoxXML(
            shapeId: shapeId, name: "Title",
            x: margin, y: margin, cx: slideWidth - margin * 2, cy: titleHeight,
            heading: nil, headingFontSize: 0, bullets: [title], bodyFontSize: 8800, centered: true
        ))
        shapeId += 1

        let contentTop = margin + titleHeight + (inchToEMU / 2)
        let contentHeight = slideHeight - contentTop - margin
        let columns = max(1, min(sections.count, 4))
        let gap = inchToEMU / 3
        let columnWidth = (slideWidth - margin * 2 - gap * (columns - 1)) / columns

        for (index, section) in sections.enumerated() {
            let column = index % columns
            let row = index / columns
            let rowHeight = contentHeight / max(1, Int(ceil(Double(sections.count) / Double(columns))))
            let x = margin + column * (columnWidth + gap)
            let y = contentTop + row * rowHeight
            shapes.append(freeformTextBoxXML(
                shapeId: shapeId, name: "Section \(index + 1)",
                x: x, y: y, cx: columnWidth, cy: rowHeight - gap,
                heading: section.heading, headingFontSize: 3200, bullets: section.bullets, bodyFontSize: 2000, centered: false
            ))
            shapeId += 1
        }

        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">
          <p:cSld>
            <p:spTree>
              <p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>
              <p:grpSpPr/>
              \(shapes.joined(separator: "\n      "))
            </p:spTree>
          </p:cSld>
          <p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr>
        </p:sld>
        """
    }

    private static func freeformTextBoxXML(
        shapeId: Int, name: String, x: Int, y: Int, cx: Int, cy: Int,
        heading: String?, headingFontSize: Int, bullets: [String], bodyFontSize: Int, centered: Bool
    ) -> String {
        var paragraphs: [String] = []
        if let heading, !heading.isEmpty {
            paragraphs.append("<a:p><a:pPr\(centered ? " algn=\"ctr\"" : "")/><a:r><a:rPr sz=\"\(headingFontSize)\" b=\"1\"/><a:t>\(xmlEscape(heading))</a:t></a:r></a:p>")
        }
        for bullet in bullets {
            let prefix = heading == nil ? "" : "\u{2022} "
            paragraphs.append("<a:p><a:pPr\(centered ? " algn=\"ctr\"" : "")/><a:r><a:rPr sz=\"\(bodyFontSize)\"/><a:t>\(prefix)\(xmlEscape(bullet))</a:t></a:r></a:p>")
        }
        if paragraphs.isEmpty {
            paragraphs.append("<a:p/>")
        }
        return """
        <p:sp>
                <p:nvSpPr><p:cNvPr id="\(shapeId)" name="\(xmlEscape(name))"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr>
                <p:spPr>
                  <a:xfrm><a:off x="\(x)" y="\(y)"/><a:ext cx="\(cx)" cy="\(cy)"/></a:xfrm>
                  <a:prstGeom prst="rect"><a:avLst/></a:prstGeom>
                </p:spPr>
                <p:txBody>
                  <a:bodyPr wrap="square" anchor="t"><a:normAutofit/></a:bodyPr>
                  <a:lstStyle/>
                  \(paragraphs.joined(separator: "\n          "))
                </p:txBody>
              </p:sp>
        """
    }

    // MARK: - Assembly

    private static func assemble(slideWidth: Int, slideHeight: Int, slidesXML: [String], docTitle: String) throws -> Data {
        let fm = FileManager.default
        let tempDir = fm.temporaryDirectory.appendingPathComponent("maziar-pptx-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempDir) }

        try write(contentTypesXML(slideCount: slidesXML.count), to: tempDir, "[Content_Types].xml")
        try write(rootRelsXML(), to: tempDir, "_rels/.rels")
        try write(corePropsXML(title: docTitle), to: tempDir, "docProps/core.xml")
        try write(appPropsXML(slideCount: slidesXML.count), to: tempDir, "docProps/app.xml")
        try write(presentationXML(slideWidth: slideWidth, slideHeight: slideHeight, slideCount: slidesXML.count), to: tempDir, "ppt/presentation.xml")
        try write(presentationRelsXML(slideCount: slidesXML.count), to: tempDir, "ppt/_rels/presentation.xml.rels")
        try write(slideMasterXML(), to: tempDir, "ppt/slideMasters/slideMaster1.xml")
        try write(slideMasterRelsXML(), to: tempDir, "ppt/slideMasters/_rels/slideMaster1.xml.rels")
        try write(slideLayoutXML(), to: tempDir, "ppt/slideLayouts/slideLayout1.xml")
        try write(slideLayoutRelsXML(), to: tempDir, "ppt/slideLayouts/_rels/slideLayout1.xml.rels")
        try write(themeXML(), to: tempDir, "ppt/theme/theme1.xml")
        for (index, xml) in slidesXML.enumerated() {
            try write(xml, to: tempDir, "ppt/slides/slide\(index + 1).xml")
            try write(slideRelsXML(), to: tempDir, "ppt/slides/_rels/slide\(index + 1).xml.rels")
        }

        let outputURL = fm.temporaryDirectory.appendingPathComponent("maziar-out-\(UUID().uuidString).pptx")
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/zip")
        process.arguments = ["-r", "-X", outputURL.path, "."]
        process.currentDirectoryURL = tempDir
        let pipe = Pipe()
        process.standardOutput = pipe
        process.standardError = pipe
        try process.run()
        process.waitUntilExit()
        guard process.terminationStatus == 0 else {
            let errData = pipe.fileHandleForReading.readDataToEndOfFile()
            throw BuildError.zipFailed(String(data: errData, encoding: .utf8) ?? "zip exited \(process.terminationStatus)")
        }
        defer { try? fm.removeItem(at: outputURL) }
        return try Data(contentsOf: outputURL)
    }

    private static func write(_ content: String, to root: URL, _ relativePath: String) throws {
        let url = root.appendingPathComponent(relativePath)
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try content.write(to: url, atomically: true, encoding: .utf8)
    }

    private static func xmlEscape(_ text: String) -> String {
        text
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }

    // MARK: - Static XML parts

    private static func contentTypesXML(slideCount: Int) -> String {
        let slideOverrides = (1...slideCount).map {
            "<Override PartName=\"/ppt/slides/slide\($0).xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slide+xml\"/>"
        }.joined(separator: "\n  ")
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
          <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
          <Default Extension="xml" ContentType="application/xml"/>
          <Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>
          <Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>
          <Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>
          <Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>
          \(slideOverrides)
          <Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>
          <Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>
        </Types>
        """
    }

    private static func rootRelsXML() -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/>
          <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>
          <Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>
        </Relationships>
        """
    }

    private static func corePropsXML(title: String) -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
          <dc:title>\(xmlEscape(title))</dc:title>
          <dc:creator>Maziar</dc:creator>
        </cp:coreProperties>
        """
    }

    private static func appPropsXML(slideCount: Int) -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">
          <Application>Maziar</Application>
          <Slides>\(slideCount)</Slides>
        </Properties>
        """
    }

    private static func presentationXML(slideWidth: Int, slideHeight: Int, slideCount: Int) -> String {
        let sldIds = (1...slideCount).map {
            "<p:sldId id=\"\(255 + $0)\" r:id=\"rIdSlide\($0)\"/>"
        }.joined(separator: "\n    ")
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">
          <p:sldMasterIdLst>
            <p:sldMasterId id="2147483648" r:id="rIdMaster1"/>
          </p:sldMasterIdLst>
          <p:sldIdLst>
            \(sldIds)
          </p:sldIdLst>
          <p:sldSz cx="\(slideWidth)" cy="\(slideHeight)"/>
          <p:notesSz cx="6858000" cy="9144000"/>
        </p:presentation>
        """
    }

    private static func presentationRelsXML(slideCount: Int) -> String {
        let slideRels = (1...slideCount).map {
            "<Relationship Id=\"rIdSlide\($0)\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide\" Target=\"slides/slide\($0).xml\"/>"
        }.joined(separator: "\n  ")
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rIdMaster1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/>
          \(slideRels)
        </Relationships>
        """
    }

    private static func slideMasterXML() -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">
          <p:cSld>
            <p:spTree>
              <p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>
              <p:grpSpPr/>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="2" name="Title Placeholder"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="title"/></p:nvPr></p:nvSpPr>
                <p:spPr><a:xfrm><a:off x="685800" y="274638"/><a:ext cx="10820400" cy="1143000"/></a:xfrm></p:spPr>
                <p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Master title style</a:t></a:r></a:p></p:txBody>
              </p:sp>
              <p:sp>
                <p:nvSpPr><p:cNvPr id="3" name="Body Placeholder"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" idx="1"/></p:nvPr></p:nvSpPr>
                <p:spPr><a:xfrm><a:off x="685800" y="1600200"/><a:ext cx="10820400" cy="4525963"/></a:xfrm></p:spPr>
                <p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Master text style</a:t></a:r></a:p></p:txBody>
              </p:sp>
            </p:spTree>
          </p:cSld>
          <p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/>
          <p:sldLayoutIdLst>
            <p:sldLayoutId id="2147483649" r:id="rIdLayout1"/>
          </p:sldLayoutIdLst>
          <p:txStyles>
            <p:titleStyle><a:lvl1pPr><a:defRPr sz="4400"/></a:lvl1pPr></p:titleStyle>
            <p:bodyStyle><a:lvl1pPr><a:defRPr sz="2800"/></a:lvl1pPr></p:bodyStyle>
            <p:otherStyle><a:lvl1pPr><a:defRPr sz="2400"/></a:lvl1pPr></p:otherStyle>
          </p:txStyles>
        </p:sldMaster>
        """
    }

    private static func slideMasterRelsXML() -> String {
        """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rIdLayout1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/>
